// Synthetic site surface only. The extension supplies all scheduling/translation logic.
export const ROOM = 'DLnative001';
export const NEXT_ROOM = 'DLnative002';
export const watchHtml = `<!doctype html><meta charset="utf-8"><title>Synthetic YouTube native chat</title>
<style>body{margin:24px;background:#101010;color:#eee;font:16px Arial}main{display:flex;gap:24px}#player-container-outer{width:760px}#movie_player{height:420px;background:#20252b;display:grid;place-items:center}ytd-live-chat-frame{display:block;width:430px}[hidden]{display:none!important}iframe{width:430px;height:590px;border:1px solid #555}button{margin:14px 8px 14px 0;padding:8px}h1{font-size:22px}</style>
<h1>Synthetic native chat integration fixture</h1><main><ytd-watch-flexy><div id="player-container-outer"><div id="movie_player"><video></video><span>Fixture video (paused)</span></div></div></ytd-watch-flexy><section><button id="hide-chat">Hide / show chat</button><ytd-live-chat-frame><iframe src="/live_chat?continuation=fixture-token"></iframe></ytd-live-chat-frame></section></main>
<script>
const fixture={room:new URL(location.href).searchParams.get('v'),paused:true};
const renderer=()=>({continuations:[{reloadContinuationData:{continuation:'fixture-token'}}],header:{sortFilterSubMenuRenderer:{subMenuItems:[{selected:false,continuation:{reloadContinuationData:{continuation:'fixture-top'}}},{selected:true,continuation:{reloadContinuationData:{continuation:'fixture-all'}}}]}}});
const flexy=document.querySelector('ytd-watch-flexy'),player=document.querySelector('#movie_player'),video=player.querySelector('video');
function metadata(){window.ytInitialPlayerResponse={videoDetails:{videoId:fixture.room,isLive:true}};window.ytInitialData={currentVideoEndpoint:{watchEndpoint:{videoId:fixture.room}},contents:{liveChatRenderer:renderer()}};flexy.playerData=window.ytInitialPlayerResponse;flexy.data=window.ytInitialData;}
metadata();player.getVideoData=()=>({video_id:fixture.room});player.getPlayerResponse=()=>window.ytInitialPlayerResponse;player.getPlayerState=()=>fixture.paused?2:1;player.isAtLiveHead=()=>true;
Object.defineProperties(video,{paused:{get:()=>fixture.paused},readyState:{get:()=>4},ended:{get:()=>false}});
fixture.replaceFrame=()=>{const old=document.querySelector('iframe'),next=old.cloneNode();next.src='/live_chat?continuation=fixture-token&generation='+Date.now();old.replaceWith(next);};
fixture.navigate=room=>{window.dispatchEvent(new Event('yt-navigate-start'));history.pushState({},'', '/watch?v='+room);fixture.room=room;metadata();fixture.replaceFrame();window.dispatchEvent(new Event('yt-navigate-finish'));};
document.querySelector('#hide-chat').onclick=()=>{const host=document.querySelector('ytd-live-chat-frame');host.hidden=!host.hidden;};
window.__YT_NATIVE_FIXTURE__=fixture;
</script>`;

export const chatHtml = `<!doctype html><meta charset="utf-8"><style>body{margin:0;background:#171717;color:#eee;font:14px Arial}header{padding:16px;border-bottom:1px solid #555}select{background:#222;color:#eee;padding:6px}yt-live-chat-item-list-renderer{display:block;height:500px;overflow-y:auto;padding:12px}yt-live-chat-text-message-renderer{display:block;padding:10px 0;line-height:1.5;border-bottom:1px solid #292929}.author{color:#86bded;margin-right:8px}.timestamp{color:#aaa;font-size:11px;margin-right:8px}#message{white-space:pre-wrap}.emoji{width:20px;height:20px;vertical-align:middle}.badge{color:#8ecca0;margin-right:6px}a{color:#83baff}</style>
<yt-live-chat-renderer><header><select aria-label="Chat filter"><option value="top">Top chat</option><option value="all" selected>Live chat</option></select></header><yt-live-chat-item-list-renderer></yt-live-chat-item-list-renderer></yt-live-chat-renderer>
<script>
const root=document.querySelector('yt-live-chat-renderer'),list=document.querySelector('yt-live-chat-item-list-renderer');
const observed={inserts:[],mutations:[],actions:[]};
root.data={header:{sortFilterSubMenuRenderer:{subMenuItems:[{selected:false,continuation:{reloadContinuationData:{continuation:'fixture-top'}}},{selected:true,continuation:{reloadContinuationData:{continuation:'fixture-all'}}}]}}};
document.querySelector('select').onchange=e=>root.data.header.sortFilterSubMenuRenderer.subMenuItems.forEach((item,index)=>item.selected=index===(e.target.value==='top'?0:1));
function remove(id){for(const row of list.children)if(row.data.id===id)row.remove();owner.visibleItems=owner.visibleItems.filter(item=>item.liveChatTextMessageRenderer.id!==id);}
const owner={visibleItems:[],handleAddChatItemAction_(action){const data=structuredClone(action.item.liveChatTextMessageRenderer);if(!data)return;remove(data.id);this.visibleItems.push({liveChatTextMessageRenderer:data});const row=document.createElement('yt-live-chat-text-message-renderer');row.data=data;row.setAttribute('data-fixture-id',data.id);const time=document.createElement('span');time.className='timestamp';time.textContent=data.timestampText?.simpleText||'12:00';const badge=document.createElement('span');badge.className='badge';badge.textContent=data.authorBadges?.length?'◆':'';const author=document.createElement('span');author.className='author';author.textContent=data.authorName?.simpleText||'Fixture author';const message=document.createElement('span');message.id='message';if(typeof data.message.simpleText==='string')message.textContent=data.message.simpleText;else for(const run of data.message.runs||[]){if(typeof run.text==='string'){const node=document.createElement(run.navigationEndpoint?'a':run.bold?'b':'span');node.textContent=run.text;if(run.navigationEndpoint)node.href='#fixture-link';message.append(node);}else if(run.emoji){const image=document.createElement('img');image.className='emoji';image.alt='';image.setAttribute('aria-label',run.emoji.accessibility?.accessibilityData?.label||'Fixture emoji');image.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20"><text y="16">⭐</text></svg>');message.append(image);}}row.append(time,badge,author,message);list.append(row);list.scrollTop=list.scrollHeight;observed.inserts.push({id:data.id,at:Date.now(),data:structuredClone(data),text:message.textContent});},handleLiveChatAction_(action){observed.actions.push(Object.keys(action)[0]);if(action.addChatItemAction)this.handleAddChatItemAction_(action.addChatItemAction);const id=action.removeChatItemAction?.targetItemId||action.markChatItemAsDeletedAction?.targetItemId;if(id)remove(id);if(action.markChatItemsByAuthorAsDeletedAction)for(const item of [...this.visibleItems])if(item.liveChatTextMessageRenderer.authorExternalChannelId===action.markChatItemsByAuthorAsDeletedAction.externalChannelId)remove(item.liveChatTextMessageRenderer.id);if(action.clearChatAction||action.clearLiveChatAction||action.removeAllChatItemsAction){list.replaceChildren();this.visibleItems=[];}if(action.replaceChatItemAction){const replacement=action.replaceChatItemAction;if(this.visibleItems.some(item=>item.liveChatTextMessageRenderer.id===replacement.targetItemId)){remove(replacement.targetItemId);this.handleAddChatItemAction_({item:replacement.replacementItem});}}},handleLiveChatActions_(actions){for(const action of actions)this.handleLiveChatAction_(action);}};
list.polymerController=owner;const originals={add:owner.handleAddChatItemAction_,action:owner.handleLiveChatAction_,batch:owner.handleLiveChatActions_};
new MutationObserver(records=>{for(const record of records){if(record.type==='characterData'){const row=record.target.parentElement.closest('yt-live-chat-text-message-renderer');if(row)observed.mutations.push({id:row.data.id,at:Date.now()});}}}).observe(list,{subtree:true,characterData:true});
window.__YT_NATIVE_CHAT__={owner,originals,observed,add:action=>owner.handleLiveChatActions_([{addChatItemAction:action}]),action:action=>owner.handleLiveChatActions_([action]),hooks:()=>({add:owner.handleAddChatItemAction_!==originals.add,action:owner.handleLiveChatAction_!==originals.action,batch:owner.handleLiveChatActions_===originals.batch})};
owner.handleAddChatItemAction_({item:{liveChatTextMessageRenderer:{id:'baseline',message:{simpleText:'既存の履歴です'},authorName:{simpleText:'Existing history'}}}});
</script>`;

export function chatAdd(id, text, extra = {}) {
  return { clientId: 'fixture-client-' + id, item: { liveChatTextMessageRenderer: { id, message: typeof text === 'string' ? { simpleText: text } : text,
    authorName: { simpleText: 'Synthetic author' }, authorExternalChannelId: 'fixture-author',
    timestampUsec: '1750000000000000', timestampText: { simpleText: '12:00' }, authorBadges: [{ liveChatAuthorBadgeRenderer: { tooltip: 'Fixture member' } }],
    contextMenuEndpoint: { commandMetadata: { webCommandMetadata: { apiUrl: '/fixture-only' } } }, ...extra } } };
}
